-- Add a reusable 300-word Chinese professional deck with pre-generated audio.
insert into public.template_decks (slug, name, description, level)
values (
  'thuong-mai-hop-dong-dam-phan-300-tu',
  'Tiếng Trung thương mại, hợp đồng và đàm phán - 300 từ',
  '300 từ vựng tiếng Trung thực tế về thị trường, khách hàng, sản phẩm, báo giá, thương lượng, hợp đồng, thanh toán, công nợ, đại lý, hậu mãi, khiếu nại và thương mại điện tử. Mỗi từ có pinyin, nghĩa tiếng Việt, câu ví dụ thực tế và hai audio tạo sẵn.',
  'Thương mại'
)
on conflict (slug) do update
set
  name = excluded.name,
  description = excluded.description,
  level = excluded.level;

with target_deck as (
  select id
  from public.template_decks
  where slug = 'thuong-mai-hop-dong-dam-phan-300-tu'
)
insert into public.template_cards (
  template_deck_id,
  chinese,
  pinyin,
  meaning_vi,
  example_cn,
  example_pinyin,
  example_vi,
  word_audio_url,
  sentence_audio_url,
  position
)
select
  target_deck.id,
  card.chinese,
  card.pinyin,
  card.meaning_vi,
  card.example_cn,
  card.example_pinyin,
  card.example_vi,
  card.word_audio_url,
  card.sentence_audio_url,
  card.position
from target_deck
cross join (
  values
    ('市场调研', 'shìchǎng tiáoyán', 'nghiên cứu thị trường', '我们的团队正在进行市场调研，了解客户需求和竞争对手情况。', 'Wǒmen de tuánduì zhèngzài jìnxíng shìchǎng tiáoyán, liǎojiě kèhù xūqiú hé jìngzhēng duìshǒu qíngkuàng.', 'Đội ngũ của chúng tôi đang tiến hành nghiên cứu thị trường để hiểu nhu cầu khách hàng và tình hình đối thủ cạnh tranh.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-300-tu/word-5466ad947f5c27fc74b5ae85.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-300-tu/sentence-fd7ab15beb0774b2bc9dcd16.mp3', 1),
    ('目标客户', 'mùbiāo kèhù', 'khách hàng mục tiêu', '明确目标客户有助于优化产品设计和营销策略。', 'Míngquè mùbiāo kèhù yǒuzhù yú yōuhuà chǎnpǐn shèjì hé yíngxiāo cèlüè.', 'Xác định khách hàng mục tiêu giúp tối ưu thiết kế sản phẩm và chiến lược tiếp thị.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-300-tu/word-49b6c733ce7b4fa6eed844e9.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-300-tu/sentence-badbb12fc84419aadb50c73a.mp3', 2),
    ('客户需求', 'kèhù xūqiú', 'nhu cầu khách hàng', '了解客户需求是制定报价方案的关键。', 'Liǎojiě kèhù xūqiú shì zhìdìng bàojià fāng''àn de guānjiàn.', 'Hiểu được nhu cầu khách hàng là then chốt để xây dựng phương án báo giá.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-300-tu/word-cf21555fd1947b3182ca4e20.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/thuong-mai-hop-dong-dam-phan-300-tu/sentence-d22fafc09c19eecd0fb973c1.mp3', 3),
